/** The glyph for a typed letter: accents are dropped ("Ằ" -> "A", "đ" -> "D") and case is ignored. */
export function bubbleGlyph(text: string): { d: string; w: number; char: string } | null {
  const base = text.normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[đĐ]/g, 'D').toUpperCase();
  const glyph = BUBBLE_GLYPHS[base];
  return glyph ? { ...glyph, char: base } : null;
}
